/*
 Problem: 3992. Rearrange String to Avoid Character Pair
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 9.4 MB (48.40%)
 Tags: Two Pointers, String, Sorting
*/
class Solution {
public:
    string rearrangeString(string s, char x, char y) {
        stable_partition(s.begin(), s.end(), [&](char c) {
           return c == y || c != x; 
        });

        return s;
    }
};
